input.command:
rm -rf .slopless && mkdir scripts && cat > scripts/lint-prose.mjs <<'EOF'
// Runs slopless on README.md and docs/**/*.md. Slopless only handles English,
// so translated directories listed in SKIP are left out.
import { readdirSync, existsSync } from "node:fs";
import { spawnSync } from "node:child_process";

const SKIP = ["docs/de", "docs/fr"];

const files = ["README.md"].filter(existsSync);
if (existsSync("docs")) {
  for (const f of readdirSync("docs", { recursive: true })) {
    const path = `docs/${f}`.replaceAll("\\", "/");
    if (!path.endsWith(".md")) continue;
    if (SKIP.some((d) => path.startsWith(`${d}/`))) continue;
    files.push(path);
  }
}

const res = spawnSync("npx", ["--no-install", "slopless", "--quiet", ...files], {
  stdio: "inherit",
  shell: process.platform === "win32",
});
process.exit(res.status ?? 2);
EOF
npm pkg set scripts.lint:prose="node scripts/lint-prose.mjs" && npm i -D slopless 2>&1 | tail -2
python3 - <<'EOF'
p=".github/workflows/ci.yml"
s=open(p).read()
s+="""  prose:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-node@v4
        with:
          node-version: 22
      - run: npm ci
      - run: npm run lint:prose
"""
open(p,"w").write(s)
EOF
npm run lint:prose | head -c 400; echo "exit ${pipestatus[1]}"
mv docs/guide.md /tmp/g.md; npm run lint:prose >/dev/null; echo "without bad file: $?"; mv /tmp/g.md docs/guide.md

